#!/usr/bin/env python3
"""Minimal nand2tetris HDL simulator for verification (combinational chips only)."""
import re, sys, os

PROJ_DIRS = ["/workspace/projects/01", "/workspace/projects/02", "/workspace/projects/03", "/workspace/projects/05"]

class Chip:
    def __init__(self, name):
        self.name = name
        self.inputs = {}   # pin -> width
        self.outputs = {}
        self.parts = []    # (chipname, [(pin, wire)])

CHIPS = {}

def parse_chip(path):
    text = open(path).read()
    text = re.sub(r"//.*", "", text)
    text = re.sub(r"/\*.*?\*/", "", text, flags=re.S)
    m = re.search(r"CHIP\s+(\w+)\s*\{(.*?)\}\s*$", text, re.S)
    name, body = m.group(1), m.group(2)
    chip = Chip(name)
    # sections
    parts_idx = body.find("PARTS:")
    decls = body[:parts_idx] if parts_idx >= 0 else body
    parts_body = body[parts_idx + 6:] if parts_idx >= 0 else ""
    for sec in re.finditer(r"(IN|OUT)\s+(.*?);", decls, re.S):
        kind, lst = sec.group(1), sec.group(2)
        for tok in lst.split(","):
            tok = tok.strip()
            if not tok:
                continue
            bm = re.match(r"(\w+)\[(\d+)\]", tok)
            if bm:
                pin, w = bm.group(1), int(bm.group(2))
            else:
                pin, w = tok, 1
            (chip.inputs if kind == "IN" else chip.outputs)[pin] = w
    for stmt in re.finditer(r"(\w+)\s*\((.*?)\)\s*;", parts_body, re.S):
        cname, conns = stmt.group(1), stmt.group(2)
        plist = []
        for conn in conns.split(","):
            conn = conn.strip()
            if not conn:
                continue
            pin, wire = conn.split("=")
            plist.append((pin.strip(), wire.strip()))
        chip.parts.append((cname, plist))
    return chip

def load_chip(name):
    if name in CHIPS:
        return CHIPS[name]
    for d in PROJ_DIRS:
        p = os.path.join(d, name + ".hdl")
        if os.path.exists(p):
            c = parse_chip(p)
            CHIPS[name] = c
            return c
    return None

# wire value resolution

def get_bits(mapping, name):
    """mapping: pin/wire name -> int value. name may be name, name[i], name[i..j], true/false"""
    if name == "true":
        return 1
    if name == "false":
        return 0
    m = re.match(r"(\w+)\[(\d+)\.\.(\d+)\]", name)
    if m:
        v = mapping[m.group(1)]
        lo, hi = int(m.group(2)), int(m.group(3))
        return (v >> lo) & ((1 << (hi - lo + 1)) - 1)
    m = re.match(r"(\w+)\[(\d+)\]", name)
    if m:
        return (mapping[m.group(1)] >> int(m.group(2))) & 1
    return mapping[name]

def set_bits(mapping, name, value):
    m = re.match(r"(\w+)\[(\d+)\.\.(\d+)\]", name)
    if m:
        base, lo, hi = m.group(1), int(m.group(2)), int(m.group(3))
        mask = ((1 << (hi - lo + 1)) - 1) << lo
        mapping[base] = (mapping.get(base, 0) & ~mask) | ((value << lo) & mask)
        return
    m = re.match(r"(\w+)\[(\d+)\]", name)
    if m:
        base, i = m.group(1), int(m.group(2))
        mapping[base] = (mapping.get(base, 0) & ~(1 << i)) | ((value & 1) << i)
        return
    mapping[name] = value

def eval_chip(name, invals, depth=0):
    assert depth < 50, "recursion loop"
    if name == "Nand":
        a, b = invals["a"], invals["b"]
        return {"out": (~(a & b)) & 1}
    chip = load_chip(name)
    assert chip is not None, f"chip {name} not found"
    wires = dict(invals)
    # initialize all internal pins/wires to 0
    for pin, w in list(chip.inputs.items()) + list(chip.outputs.items()):
        wires.setdefault(pin, 0)
    # iterate parts to fixpoint (combinational)
    for _ in range(200):
        changed = False
        snapshot = dict(wires)
        for cname, conns in chip.parts:
            sub = load_chip(cname) if cname != "Nand" else None
            sub_in = {}
            sub_out_wires = []
            for pin, wire in conns:
                # determine if pin is an input of the subchip
                if cname == "Nand":
                    is_in = pin in ("a", "b")
                else:
                    is_in = pin in sub.inputs
                if is_in:
                    sub_in[pin] = get_bits(snapshot, wire)
                else:
                    sub_out_wires.append((pin, wire))
            outvals = eval_chip(cname, sub_in, depth + 1)
            for pin, wire in sub_out_wires:
                v = outvals[pin]
                if get_bits(snapshot, wire) != v:
                    changed = True
                set_bits(wires, wire, v)
        if not changed and _ > 0:
            break
    return {pin: wires[pin] for pin in chip.outputs}

def test_halfadder():
    for a in (0, 1):
        for b in (0, 1):
            r = eval_chip("HalfAdder", {"a": a, "b": b})
            assert r["sum"] == (a ^ b) and r["carry"] == (a & b), (a, b, r)
    print("HalfAdder OK")

def test_fulladder():
    for a in (0, 1):
        for b in (0, 1):
            for c in (0, 1):
                r = eval_chip("FullAdder", {"a": a, "b": b, "c": c})
                s = a + b + c
                assert r["sum"] == s % 2 and r["carry"] == s // 2, (a, b, c, r)
    print("FullAdder OK")

def test_add16():
    import random
    cases = [(0, 0), (1, 1), (0xFFFF, 1), (0x1234, 0x5678), (0xFFFF, 0xFFFF), (0b1010101010101010, 0b0101010101010101)]
    random.seed(1)
    cases += [(random.randint(0, 0xFFFF), random.randint(0, 0xFFFF)) for _ in range(20)]
    for a, b in cases:
        r = eval_chip("Add16", {"a": a, "b": b})
        assert r["out"] == (a + b) & 0xFFFF, (a, b, r)
