def test_inc16():
    import random
    random.seed(2)
    cases = [0, 1, 0xFFFF, 0x7FFF] + [random.randint(0, 0xFFFF) for _ in range(20)]
    for a in cases:
        r = eval_chip("Inc16", {"in": a})
        assert r["out"] == (a + 1) & 0xFFFF, (a, r)
    print("Inc16 OK")

