    if zx: x = 0
    if nx: x ^= 0xFFFF
    if zy: y = 0
    if ny: y ^= 0xFFFF
    o = (x + y) & 0xFFFF if f else (x & y)
    if no: o ^= 0xFFFF
    zr = 1 if o == 0 else 0
    ng = (o >> 15) & 1
