# parts propagate within a single pass
for _ in range(len(chip.parts) + 2):
    changed = False
    for cname, conns in chip.parts:
        sub = load_chip(cname) if cname != "Nand" else None
        sub_in = {}
        sub_out_wires = []
        if sub is not None:
            for p, w in sub.inputs.items():
                sub_in[p] = 0
        elif cname == "Nand":
            sub_in = {"a": 0, "b": 0}
        for pin, wire in conns:
            # determine if pin is an input of the subchip
            base_pin = re.match(r"(\w+)", pin).group(1)
            if cname == "Nand":
                is_in = base_pin in ("a", "b")
            else:
                is_in = base_pin in sub.inputs
            if is_in:
                set_bits(sub_in, pin, get_bits(wires, wire))
            else:
                sub_out_wires.append((pin, wire))
        outvals = eval_chip(cname, sub_in, depth + 1)
        for pin, wire in sub_out_wires:
            v = get_bits(outvals, pin)
            if get_bits(wires, wire) != v:
                changed = True
            set_bits(wires, wire, v)
    if not changed:
        break
result = {pin: wires[pin] for pin in chip.outputs}
CACHE[key] = result
return result

