#!/usr/bin/env python3
"""Minimal nand2tetris .tst interpreter + .cmp comparator (scratch tool)."""
import re, os, sys, time
from hdsim import (Lib, Sim, strip_comments)

TOKEN_RE = re.compile(r'''
      "(?:[^"\\]|\\.)*"              # quoted string
    | %[A-Za-z][0-9A-Fa-f.]*         # %B1010 / %X2000 / %D5 / %S1.4.1 ...
    | [A-Za-z_][\w.-]*(?:\[\d*\])?   # identifier, filename, Name[i], Name[]
    | -?\d+                          # number
    | <>                             # not-equal
    | [{},;=]                        # punctuation
''', re.X)

def tokenize(text):
    return TOKEN_RE.findall(strip_comments(text))

class P:
    def __init__(self, toks):
        self.t = toks; self.i = 0
    def peek(self):
        return self.t[self.i] if self.i < len(self.t) else None
    def next(self):
        tok = self.t[self.i]; self.i += 1; return tok

def parse_num(tok):
    if tok.startswith('%B'): return int(tok[2:], 2)
    if tok.startswith('%X'): return int(tok[2:], 16)
    if tok.startswith('%D'): return int(tok[2:])
    return int(tok)

def parse_cmds(p, end=None):
    cmds = []
    while p.peek() is not None and p.peek() != end:
        tok = p.next()
        if tok == 'load':
            cmds.append(('load', p.next())); swallow(p)
        elif tok in ('output-file', 'compare-to'):
            cmds.append((tok, p.next())); swallow(p)
        elif tok == 'output-list':
            cols = []
            while p.peek() != ';':
                name = p.next(); fmt = p.next()
                cols.append((name, fmt[1] if fmt.startswith('%') else '?'))
            p.next()  # ';'
            cmds.append(('output-list', cols))
        elif tok == 'set':
            name = p.next(); val = parse_num(p.next()); swallow(p)
            cmds.append(('set', name, val))
        elif tok in ('tick', 'tock', 'eval', 'output', 'clear-echo'):
            swallow(p)
            cmds.append((tok,))
        elif tok == 'echo':
            p.next(); swallow(p)  # ignore string
        elif tok == 'repeat':
            n = int(p.next()); expect(p, '{')
            body = parse_cmds(p, '}'); p.next()
            cmds.append(('repeat', n, body))
        elif tok == 'while':
            var = p.next(); op = p.next(); val = parse_num(p.next())
            expect(p, '{')
            body = parse_cmds(p, '}'); p.next()
            cmds.append(('while', var, op, val, body))
        elif tok == 'ROM32K':
            p.next()  # 'load'
            cmds.append(('romload', p.next())); swallow(p)
        else:
            raise ValueError('unexpected token %r' % tok)
    return cmds

def swallow(p):
    if p.peek() in (',', ';'):
        p.next()

def expect(p, tok):
    got = p.next()
    if got != tok:
        raise ValueError('expected %r got %r' % (tok, got))

def run_tst(tst_path, lib):
    cmds = parse_cmds(P(tokenize(open(tst_path).read())))
    basedir = os.path.dirname(tst_path)
    sim = None
    cols = []
    rows = []
    ctx = {'cmp': None}

    def colval(name, fmt):
        if name == 'time':
            return '%d%s' % (sim.cycle, sim.phase) if sim.phase == '+' \
                else str(sim.cycle)
        if name in sim.d.inp or name in sim.d.outp:
            return sim.out(name)
        return sim.probe(name)

    def exec_cmds(cs):
        nonlocal sim, cols
        for c in cs:
            k = c[0]
            if k == 'load':
                sim = Sim(lib, c[1][:-4])
            elif k == 'compare-to':
                ctx['cmp'] = c[1]
            elif k == 'output-file':
                pass
            elif k == 'output-list':
                cols = c[1]
            elif k == 'set':
                name, val = c[1], c[2]
                m = re.match(r'^(\w+)\[(\d+)\]$', name)
                if m and m.group(1).startswith('RAM'):
                    sim.poke(m.group(1), int(m.group(2)), val & 0xFFFF)
                else:
                    sim.set(name, val)
            elif k == 'tick':
                sim.tick()
            elif k == 'tock':
                sim.tock()
            elif k == 'eval':
                sim.eval()
            elif k == 'output':
                rows.append([colval(n, f) for n, f in cols])
            elif k == 'repeat':
                for _ in range(c[1]):
                    exec_cmds(c[2])
            elif k == 'while':
                var, op, target, body = c[1], c[2], c[3], c[4]
                # simulate the user holding the requested key down
                if sim.kb_inst is not None:
                    sim.kb_inst.kb = target & 0xFFFF
                    sim.settle()
                it = 0
                while (sim.out(var) != (target & 0xFFFF)) == (op == '<>'):
                    exec_cmds(body)
                    it += 1
                    if it > 1000:
                        raise RuntimeError('while loop stuck on %s %s %s'
                                           % (var, op, target))
            elif k == 'romload':
                sim.load_rom(os.path.join(basedir, c[1]))
            elif k in ('clear-echo',):
                pass
    exec_cmds(cmds)
    return sim, cols, rows, ctx['cmp']

def parse_cmp(path):
    rows = []
    for line in open(path):
        line = line.rstrip('\n')
        if not line.strip().startswith('|'):
            continue
        cells = [c.strip() for c in line.split('|')[1:-1]]
        rows.append(cells)
    return rows[0], rows[1:]

def colwidth(sim, name):
    if name in sim.d.inp:
        return sim.d.inp[name]
    if name in sim.d.outp:
        return sim.d.outp[name]
    return 16  # internal probes (registers, RAM words, PC)

def compare(sim, cols, my_rows, cmp_rows):
    """Returns list of mismatch dicts."""
    mm = []
    if len(my_rows) != len(cmp_rows):
        mm.append({'row': -1, 'col': '(row count)',
                   'expected': len(cmp_rows), 'actual': len(my_rows)})
    for i, (mine, exp) in enumerate(zip(my_rows, cmp_rows)):
        for j, (name, fmt) in enumerate(cols):
            e = exp[j] if j < len(exp) else ''
            if e and set(e) == {'*'}:
                continue  # wildcard (e.g. outM when writeM==0)
            a = mine[j]
            if fmt == 'S':
                ok = (str(a) == e)
                shown = a
            elif fmt == 'B':
                ok = (int(e, 2) == a); shown = format(a, 'b')
            elif fmt == 'X':
                ok = (int(e, 16) == a); shown = format(a, 'x')
            else:  # D: signed decimal
                w = colwidth(sim, name)
                av = a - (1 << w) if a >= (1 << (w - 1)) else a
                ok = (int(e) == av); shown = av
            if not ok:
                mm.append({'row': i, 'time': mine[0], 'col': name,
                           'expected': e, 'actual': shown})
    return mm

def run_one(tst_path, lib, verbose=True):
    t0 = time.time()
    sim, cols, rows, cmpname = run_tst(tst_path, lib)
    hdr, cmp_rows = parse_cmp(os.path.join(os.path.dirname(tst_path), cmpname))
    mm = compare(sim, cols, rows, cmp_rows)
    dt = time.time() - t0
    status = 'PASS' if not mm else 'FAIL'
    if verbose:
        print('%-28s %s  (%d rows, %.1fs)' %
              (os.path.basename(tst_path), status, len(rows), dt))
    for m in mm[:12]:
        if m['row'] == -1:
            print('    row count mismatch: expected %s got %s'
                  % (m['expected'], m['actual']))
        else:
            print('    row %s (time=%s) col %s: expected %s, actual %s'
                  % (m['row'], m['time'], m['col'], m['expected'], m['actual']))
    if len(mm) > 12:
        print('    ... and %d more mismatches' % (len(mm) - 12))
    return not mm

